async function folderParent(notebookId:string,parentId:string|null|undefined){
  if(!parentId)return null;
  const all=await db.select({id:folders.id,parentId:folders.parentId,trashedAt:folders.trashedAt}).from(folders).where(eq(folders.notebookId,notebookId));
  const parent=all.find(folder=>folder.id===parentId&&!folder.trashedAt);
  if(!parent)throw fail("VALIDATION","父目录不属于目标笔记本");
  const parentOf=new Map(all.filter(folder=>!folder.trashedAt).map(folder=>[folder.id,folder.parentId]));
  let depth=0;
  const seen=new Set<string>();
  for(let current:string|null|undefined=parent.id;current;current=parentOf.get(current)){
    if(seen.has(current))throw fail("VALIDATION","目录结构存在环");
    seen.add(current);
    depth++;
    if(depth>=FOLDER_DEPTH_LIMIT)throw fail("VALIDATION",`目录最多嵌套 ${FOLDER_DEPTH_LIMIT} 层`);
  }
  return parent.id;
}
